import{_ as a,o as d,c as e,a2 as n}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"05 · 声音与剪辑","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/05-sound-edit.md","filePath":"lab/shuangyu-fries/honey-butter/05-sound-edit.md","lastUpdated":1786871523000}'),s={name:"lab/shuangyu-fries/honey-butter/05-sound-edit.md"};function i(r,t,l,o,h,p){return d(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="_05-·-声音与剪辑" tabindex="-1">05 · 声音与剪辑 <a class="header-anchor" href="#_05-·-声音与剪辑" aria-label="Permalink to &quot;05 · 声音与剪辑&quot;">​</a></h1><blockquote><p>正式画面粗剪通过后执行。视频模型自带音频只作动作参考，不直接进入最终混音。</p></blockquote><h2 id="声音策略" tabindex="-1">声音策略 <a class="header-anchor" href="#声音策略" aria-label="Permalink to &quot;声音策略&quot;">​</a></h2><p>本片的 A / B / C 必须听起来是同一种产品在三种动作下产生的声音，而不是三个无关音效。素材可以来自产品 Foley 实录，也可以使用 AI 音效模型逐条定制；无论来源如何，都要独立生成或录制，并保留来源记录。</p><p>若最终没有使用真实产品实录，对外文案只称「声音选择题」或「声纹挑战」，不表述为「原声实录」「真实盲测」。</p><h2 id="声音资产表" tabindex="-1">声音资产表 <a class="header-anchor" href="#声音资产表" aria-label="Permalink to &quot;声音资产表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>声音</th><th>性格</th><th>生成 / 录制要求</th><th>后期处理</th></tr></thead><tbody><tr><td>A · 单根折断</td><td>短、亮、干、起音清楚</td><td>单次脆裂，尾音短，无包装和环境声</td><td>轻微削低频，保留碎裂高频</td></tr><tr><td>B · 双根折断</td><td>更厚、两层、带 20–60ms 微时差</td><td>独立制作，不复制 A 简单叠两层</td><td>控制峰值，保留两次不同起音</td></tr><tr><td>C · 咬下</td><td>中低频更完整，有食用感但不黏</td><td>一次自然咬断，不含吞咽、呼吸和湿润口腔声</td><td>删除令人不适的口腔细节</td></tr><tr><td>调味颗粒</td><td>轻、细、干燥</td><td>少量粉末落在纸面的高频细节</td><td>只用于 remix，低于主咔嚓</td></tr><tr><td>包装接触</td><td>轻微、克制</td><td>杯体落台或包装层移动</td><td>只用于落版，不制造塑料空响</td></tr><tr><td>提示音</td><td>清楚但不游戏化</td><td>0.1 秒以内的短音</td><td>仅片头与答案揭晓使用</td></tr></tbody></table><h2 id="ai-音效-prompt-基准" tabindex="-1">AI 音效 Prompt 基准 <a class="header-anchor" href="#ai-音效-prompt-基准" aria-label="Permalink to &quot;AI 音效 Prompt 基准&quot;">​</a></h2><h3 id="a-·-单根折断" tabindex="-1">A · 单根折断 <a class="header-anchor" href="#a-·-单根折断" aria-label="Permalink to &quot;A · 单根折断&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single short, bright and dry snap of one rigid crispy potato baton breaking cleanly at the center,</span></span>
<span class="line"><span>close-mic food Foley, crisp high-frequency detail, tiny natural crumb tail, no reverb, no music,</span></span>
<span class="line"><span>no packaging sound, no voice, no wet mouth sound, duration under 0.6 seconds.</span></span></code></pre></div><h3 id="b-·-双根折断" tabindex="-1">B · 双根折断 <a class="header-anchor" href="#b-·-双根折断" aria-label="Permalink to &quot;B · 双根折断&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Two rigid crispy potato batons snapping almost together with a natural 20-60 millisecond offset,</span></span>
<span class="line"><span>slightly fuller and denser than a single snap, two distinct brittle layers, close-mic dry food Foley,</span></span>
<span class="line"><span>short natural crumb tail, no reverb, no music, no impact boom, no packaging, duration under 0.7 seconds.</span></span></code></pre></div><h3 id="c-·-咬下" tabindex="-1">C · 咬下 <a class="header-anchor" href="#c-·-咬下" aria-label="Permalink to &quot;C · 咬下&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>One natural bite through a dry crispy potato baton, a clean brittle crack with a slightly fuller</span></span>
<span class="line"><span>low-mid body than a hand snap, appetizing close-mic food Foley, minimal mouth detail, no chewing loop,</span></span>
<span class="line"><span>no saliva, no swallowing, no breathing, no voice, no music, duration under 0.8 seconds.</span></span></code></pre></div><p>同一工具内尽量固定模型、采样设置和空间感。A、B、C 各生成 6–8 条，选片时优先判断是否像同一种食品材质，再判断哪一条更“爽”。</p><h2 id="声画同步" tabindex="-1">声画同步 <a class="header-anchor" href="#声画同步" aria-label="Permalink to &quot;声画同步&quot;">​</a></h2><ul><li>每条声音峰值与画面第一次真实断裂或咬断的帧对齐，不能提前制造假冲击。</li><li>视频模型生成的随机声不参与最终比较，导入剪辑时先全部静音。</li><li>A 与 B 保持相同基础响度，不能仅靠把 B 放大来制造差异。</li><li>C 可以更厚，但不能出现吞咽、黏声或夸张低频冲击。</li><li>三条最终声音生成波形后，再制作镜头 05 和 07；不能先画装饰波形再反推声音。</li></ul><h2 id="剪辑节拍" tabindex="-1">剪辑节拍 <a class="header-anchor" href="#剪辑节拍" aria-label="Permalink to &quot;剪辑节拍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>剪辑职责</th><th>声音处理</th></tr></thead><tbody><tr><td>00:00.0–00:00.9</td><td>建立问题与口味身份</td><td>0.1 秒提示音后留白</td></tr><tr><td>00:00.9–00:04.2</td><td>A / B / C 连续测试</td><td>不加音乐和转场音；声音峰值逐帧对齐动作</td></tr><tr><td>00:04.2–00:05.4</td><td>留出作答</td><td>三声尾音以极低音量快速回放，不强调某一选项</td></tr><tr><td>00:05.4–00:08.1</td><td>A–B–C–断面 remix</td><td>音乐第一次进入；第四拍最重，主咔嚓高于伴奏</td></tr><tr><td>00:08.1–00:09.0</td><td>答案停顿</td><td>先静音 0.1 秒，再用轻提示音揭晓</td></tr><tr><td>00:09.0–00:10.3</td><td>断面证据</td><td>单独回放最干净的一声咔嚓</td></tr><tr><td>00:10.3–00:12.0</td><td>包装落版与循环</td><td>音乐在产品名出现时收住；11.6 秒最后一声接回片头</td></tr></tbody></table><h2 id="remix-结构" tabindex="-1">remix 结构 <a class="header-anchor" href="#remix-结构" aria-label="Permalink to &quot;remix 结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 拍：A 单根折断，短、亮</span></span>
<span class="line"><span>第 2 拍：B 双根折断，更厚、带自然微时差</span></span>
<span class="line"><span>第 3 拍：C 咬下，中低频更完整</span></span>
<span class="line"><span>第 4 拍：最干净的主咔嚓 + 镜头 08 断面，最重收束</span></span></code></pre></div><p>调味颗粒可作为低音量高频装饰，不增加与画面无关的爆炸、金属、玻璃或电影冲击音。</p><h2 id="字幕与版式" tabindex="-1">字幕与版式 <a class="header-anchor" href="#字幕与版式" aria-label="Permalink to &quot;字幕与版式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>元素</th><th>规则</th></tr></thead><tbody><tr><td>主问题</td><td>两行以内，第一帧完整出现，不逐字动画</td></tr><tr><td>A / B / C</td><td>固定在左上安全区；位置、字号、颜色一致</td></tr><tr><td>波形</td><td>由最终声音生成；线条清楚，不做装饰性假波形</td></tr><tr><td>答案</td><td>只写「答案：都是。」不补解释小字</td></tr><tr><td>核心文案</td><td>「味道听不见，脆可以。」保持一行或自然分成两行</td></tr><tr><td>落版</td><td>品牌名、产品名、口味名由后期排版，不让模型写字</td></tr></tbody></table><p>主色为奶油白、自然浅金与少量黑色。A / B / C 可以使用三种低饱和辅助色，但产品本身不跟随选项变色。</p><h2 id="输出版本" tabindex="-1">输出版本 <a class="header-anchor" href="#输出版本" aria-label="Permalink to &quot;输出版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th style="text-align:right;">时长</th><th>用途</th><th>调整原则</th></tr></thead><tbody><tr><td>主版</td><td style="text-align:right;">12 秒</td><td>原生发布与完整互动</td><td>保留问题、三声、作答、反转、证据和落版</td></tr><tr><td>投放版</td><td style="text-align:right;">6 秒</td><td>信息流快速测试</td><td>保留问题、A / B / C 快切、答案与简化落版</td></tr><tr><td>A / B / C 单条</td><td style="text-align:right;">每条 1–2 秒</td><td>评论回复和二次剪辑</td><td>保留对应动作和独立声音，不加音乐</td></tr><tr><td>remix 素材</td><td style="text-align:right;">6–8 秒</td><td>后续声纹内容</td><td>只用已建立的声音资产重排，不伪装新测试</td></tr></tbody></table><h2 id="本步审核" tabindex="-1">本步审核 <a class="header-anchor" href="#本步审核" aria-label="Permalink to &quot;本步审核&quot;">​</a></h2><ul><li>[ ] 视频模型原始声音已全部静音或移出正式轨道</li><li>[ ] A、B、C 听起来属于同一种食品材质，但动作层次可区分</li><li>[ ] 每条声音均有来源、Prompt / 原始文件与采用版本记录</li><li>[ ] 三条波形由最终采用的声音生成</li><li>[ ] 前 4.2 秒完全无背景音乐和无关转场音</li><li>[ ] 落版尾声可以自然循环回第一帧</li></ul><hr><p><strong>上一步</strong> ← <a href="./04-storyboard">04 · 分镜</a> ｜ <strong>下一步</strong> → <a href="./06-release-review">06 · 发布与验收</a></p>`,31)])])}const b=a(s,[["render",i]]);export{u as __pageData,b as default};
